package dev.studyforge.banking.application; import dev.studyforge.banking.domain.*; import java.util.*; public final class HistoryService{private final UnitOfWork uow;public HistoryService(UnitOfWork u){uow=u;}public List<Transaction> all(){return uow.execute((a,t)->t.findAll());}public List<Transaction> forAccount(AccountId id){return uow.execute((a,t)->{a.findById(id).orElseThrow(()->new AccountNotFoundException(id));return t.findAll().stream().filter(x->id.equals(x.source())||id.equals(x.destination())).toList();});}}
